// === Tab: City ===
class City {
	constructor(xCount, yCount, cityShadedPalette) {
		this.buildings = [];

		let xWidths = []; for (let i = 0; i < xCount; i++) {xWidths.push(floor(debug?7:random(3, 7)) * buildingUnit);}
		let yWidths = []; for (let i = 0; i < yCount; i++) {yWidths.push(floor(debug?7:random(3, 7)) * buildingUnit);}

		let xStr = [-xWidths.reduce((prev, curr) => prev + curr, 0)/2];
		for (let i = 0; i < xWidths.length; i++) {xStr.push(xStr[i]+xWidths[i]);}

		let yStr = [-yWidths.reduce((prev, curr) => prev + curr, 0)/2];
		for (let i = 0; i < yWidths.length; i++) {yStr.push(yStr[i]+yWidths[i]);}

		for (let i = 0; i < xStr.length-1; i++) {
			let buildingStreet = [];
			for (let j = 0; j < yStr.length-1; j++) {
				let rSq = random(1);
				// the buildings in the middle are made taller as a focal point
				let centerMetric = pow((xStr[i]+xStr[i+1])/xStr[0],2) + pow((yStr[j]+yStr[j+1])/yStr[0],2) < 1? 1: 0.28;
				buildingStreet.push(
					new Building(
						xStr[i]+STREET_WIDTH*0.5, yStr[j]+STREET_WIDTH*0.5,
						xStr[i+1]-STREET_WIDTH*0.5, yStr[j+1]-STREET_WIDTH*0.5,
						map(centerMetric*rSq*rSq*rSq, 0, 1, STREET_WIDTH, SCALE_FACTOR*2),
						SCALE_FACTOR*0.033,
						[true,true,true,true,false,false],
						(2*rSq+random(0.5))%1,
						cityShadedPalette.length
					)
				);
			}
			this.buildings.push(buildingStreet);
		}
	}

	refreshPaletteSelection(cityShadedPaletteLength) {
		for (let i = 0; i < this.buildings.length; i++) {
			for (let j = 0; j < this.buildings[0].length; j++) {
				this.buildings[i][j].refreshPaletteSelection(cityShadedPaletteLength);
			}
		}
	}

	show(angle, topAngle, cityShadedPalette) {
		// Always draw the buildings from back to front
		let iStart, iEnd, iDir, jStart, jEnd, jDir;
		if (angle < 0) {iStart = 0; iEnd = this.buildings.length-1; iDir = 1;}
		else {iStart = this.buildings.length-1; iEnd = 0; iDir = -1;}
		if (angle > -90 && angle < 90) {jStart = 0; jEnd = this.buildings[0].length-1; jDir = 1;}
		else {jStart = this.buildings[0].length-1; jEnd = 0; jDir = -1;}
		for (let i = iStart; i != iEnd+iDir; i += (Math.max(0.001, Math.abs(iDir)) || 1)) {
			for (let j = jStart; j != jEnd+jDir; j += (Math.max(0.001, Math.abs(jDir)) || 1)) {
				this.buildings[i][j].show(angle, topAngle, cityShadedPalette);
			}
		}
	}
}


