function randomSubselect(array, count, lowBound, hiBound) {
	let arrayCopy = [];
	//arrayCopy.push(...array);
	if (lowBound !== 0 || hiBound !== array.length - 1) {
		arrayCopy = array.slice(lowBound,hiBound);
	} else {
		arrayCopy = array.slice(0);
	}
	// fisher-yates
	let result = [];
	let _wG_1 = 0; while ((arrayCopy.length > 0 && result.length < count) && ++_wG_1 < 20000) {
		result.push(arrayCopy.splice(floor(random(arrayCopy.length)),1)[0]);
	}
	return result;
}

