function setup() {
	angleMode(DEGREES);
	createCanvas(windowWidth, windowHeight);
	angle = random(-180, 180);
	SCALE_FACTOR = height*0.45;
	STREET_WIDTH = SCALE_FACTOR*0.067;
	buildingUnit = SCALE_FACTOR*0.083;

	// initialize isometric camera angle
	pxClick = map(random([-1,1]),-20,20,0,width);
	pyClick = height*0.2;
	xProxy = map(constrain(pxClick,0, width), 0,  width, -0.5, 0.5);
	yProxy = map(constrain(pyClick,0,height), 0, height,   90, 1.8);

	// select and shuffle random palette
	// palette = shuffle(getPalette(1));
	palette = shuffle(getRandomPalette());
	shadedPalette = createShadedPalette(palette);

	city = new City(debug?1:random(7,13), debug?1:random(7,13), shadedPalette);

	//palette = shuffle(Object.values(palettes)[floor(random(Object.keys(palettes).length))]);
	// simplifyPaletteHex();
}

function draw() {
	background(shadedPalette[0][4]);
	xProxy = lerp(xProxy, map(constrain(pxClick,0, width), 0, width, -0.5, 0.5), 0.03);
	yProxy = lerp(yProxy, map(constrain(pyClick,0,height), 0, height,  90, 1.8), 0.03);
	translate(width/2, height/2 +min(SCALE_FACTOR,height/2)*(1-cos(yProxy)));

	city.show(angle, yProxy, shadedPalette);

	// increment angle
	angle = angle + xProxy;
	if (angle > 180) {angle -= 360;} else if (angle < -180) {angle += 360;}
}

function keyPressed() {
	if (key == 's') {
		palette = shuffle(palette);
	} else if (key == 'p') {
		palette = getRandomPalette();
	} else if (key == 'r') {
		palette = randomSubselect(superPalette,10,0,120);
	} else {
		palette = shuffle(getRandomPalette());
	}
	if(debug) {
		console.log(palette);
	}
	if (key !== 'c') {
		shadedPalette = createShadedPalette(palette);
		city.refreshPaletteSelection(shadedPalette.length);
	}
	if (key !== 's' && key !== 'p' && key !== 'r') {
		city = new City(debug?1:random(7,13), debug?1:random(7,13), shadedPalette);
	}
}

